#!/usr/bin/env python3
# ID: decode_timestamps_55AA_final.py v2025-09-29.5

# Strict decoder for 0x55AA + ch + PICstop_low32 + tof + CRC8 (Dallas/Maxim)
#
# Frame (12 bytes):
#   [0]=0x55, [1]=0xAA, [2]=ch, [3..6]=PICstop_low32 LE, [7..10]=tof LE, [11]=CRC8(payload[2..10])
#
# Features:
# - Byte-scan for 0x55AA, CRC verify on [2..10]
# - Channel whitelist (--channels A B) recommended
# - Per-channel first-frame filter (implicit via --min-seconds): drop frames with ts < min_seconds
#   (default 1.0 s). This removes initial priming frames safely and does not affect true rollovers.
# - Per-channel rollover extension (wrap only if drop > 2^32 - wrap_margin_ticks)
# - Per-channel routing with hard assertion at write-out (no cross-channel leakage)
# - Per-channel spacing stats (min/avg/max Δt) to verify one event per second
# - Interleaved (--interleave) or per-channel outputs (default)
# - .bad sidecar optional for CRC-failed frames
#
# Usage examples:
#   python decode_timestamps_55AA_final.py --infile data.bin --outfile ts --channels A B
#   python decode_timestamps_55AA_final.py --infile data.bin --outfile ts.txt --channels A B --interleave
#
# Notes:
# - PS_PER_TICK defaults to 100,000,000 ps (100 µs)
# - CRC-8 Dallas/Maxim: poly 0x31 (reflected 0x8C), init 0x00, refIn/refOut true

import argparse
import os
import statistics
import sys
from typing import Dict, List, Optional, Tuple

HDR0, HDR1 = 0x55, 0xAA
FRAME_LEN = 12
TWO32 = 1 << 32
PS_PER_TICK_DEFAULT = 100_000_000  # 100 microseconds in picoseconds


def parse_args():
    p = argparse.ArgumentParser(
        description="Strict decode 0x55AA+CRC frames (ID v2025-09-29.5)"
    )
    p.add_argument("--infile", required=True)
    p.add_argument("--outfile", required=True)
    p.add_argument("--channels", nargs="+", help="Whitelist channels, e.g., A B")
    p.add_argument("--interleave", action="store_true")
    p.add_argument("--ps-per-tick", type=int, default=PS_PER_TICK_DEFAULT)
    p.add_argument("--wrap-margin-ticks", type=int, default=100_000)
    p.add_argument("--min-seconds", type=float, default=1.0, help="Drop frames with ts < this (default 1.0)")
    p.add_argument("--keep-bad", action="store_true")
    p.add_argument("--max-errors", type=int, default=1_000_000)
    p.add_argument(
        "--debug", action="store_true", help="Print first 40 DBG lines to stderr"
    )
    return p.parse_args()


def crc8_maxim(b: bytes) -> int:
    crc = 0
    for x in b:
        crc ^= x
        for _ in range(8):
            crc = ((crc >> 1) ^ 0x8C) if (crc & 1) else (crc >> 1)
    return crc & 0xFF


def load(path: str) -> bytes:
    with open(path, "rb") as f:
        return f.read()


def ch_name(ch: int) -> str:
    return chr(ch) if 32 <= ch <= 126 else f"0x{ch:02X}"


def main():
    a = parse_args()
    d = load(a.infile)
    n = len(d)

    # Whitelist
    wl: Optional[set[int]] = None
    if a.channels:
        wl = set()
        for s in a.channels:
            if len(s) == 1:
                wl.add(ord(s))
            else:
                try:
                    v = int(s, 0)
                    if 0 <= v <= 255:
                        wl.add(v)
                except Exception:
                    pass

    frames_ok = 0
    crc_fail = 0
    scanned = 0
    bad = bytearray()

    last_low32: Dict[int, Optional[int]] = {}
    wraps: Dict[int, int] = {}

    interleaved: List[Tuple[float, int, str]] = []
    per_ch: Dict[int, List[Tuple[float, int, str]]] = {}

    dbg_left = 40 if a.debug else 0

    i = 0
    while i + FRAME_LEN <= n:
        if d[i] != HDR0 or d[i + 1] != HDR1:
            i += 1
            scanned += 1
            continue

        frame = d[i : i + FRAME_LEN]
        payload = frame[2:11]
        cfil = frame[11]
        cc = crc8_maxim(payload)
        if cc != cfil:
            crc_fail += 1
            if a.keep_bad:
                bad.extend(frame)
            i += 1
            scanned += 1
            if crc_fail > a.max_errors:
                print("Too many CRC failures; abort.", file=sys.stderr)
                break
            continue

        ch = frame[2]
        if wl is not None and ch not in wl:
            i += 1
            scanned += 1
            continue

        low32 = int.from_bytes(frame[3:7], "little", signed=False)
        tof = int.from_bytes(frame[7:11], "little", signed=False)

        if dbg_left > 0:
            print(
                f"DBG off={i} ch={ch_name(ch)} low32=0x{low32:08X} tof=0x{tof:08X}",
                file=sys.stderr,
            )
            dbg_left -= 1

        # Rollover
        if ch not in last_low32:
            last_low32[ch] = None
        if ch not in wraps:
            wraps[ch] = 0

        prev = last_low32[ch]
        if prev is not None and low32 < prev:
            drop = prev - low32
            if drop > (TWO32 - max(0, a.wrap_margin_ticks)):
                wraps[ch] += 1
        last_low32[ch] = low32

        picstop_full = (wraps[ch] << 32) | low32
        ts_ps = (picstop_full * a.ps_per_tick) - tof
        ts = ts_ps / 1e12

        # Minimum timestamp filter: drop early/priming frames
        if ts < a.min_seconds:
            i += FRAME_LEN
            continue

        line = f"{ts:.12f} ch{ch_name(ch)}\n"
        if a.interleave:
            interleaved.append((ts, ch, line))
        else:
            per_ch.setdefault(ch, []).append((ts, ch, line))

        frames_ok += 1
        i += FRAME_LEN

    # Write outputs with hard routing assertion and spacing stats
    try:
        if a.interleave:
            interleaved.sort(key=lambda x: x[0])
            with open(a.outfile, "w", encoding="utf-8", newline="\n") as f:
                for ts, ch_out, line in interleaved:
                    f.write(line)
        else:
            if not per_ch:
                print("No frames decoded for selected channels.", file=sys.stderr)
            root, ext = os.path.splitext(a.outfile)
            stats: Dict[int, Tuple[float, float, float, float]] = {}
            for ch_key, rows in per_ch.items():
                rows.sort(key=lambda x: x[0])
                chn = ch_name(ch_key)
                path = f"{root}_{chn}{ext or '.txt'}"
                deltas = []
                last_ts = None
                with open(path, "w", encoding="utf-8", newline="\n") as f:
                    for ts, ch_out, line in rows:
                        if ch_out != ch_key:
                            raise RuntimeError(
                                f"Routing mismatch: saw ch={ch_name(ch_out)} in file for ch={ch_name(ch_key)}"
                            )
                        f.write(line)
                        if last_ts is not None:
                            deltas.append(ts - last_ts)
                        last_ts = ts
                if deltas:
                    stats[ch_key] = (
                        min(deltas),
                        max(deltas),
                        float(statistics.mean(deltas)),
                        float(len(deltas)),
                    )
                else:
                    stats[ch_key] = (0.0, 0.0, 0.0, 0.0)

            for ch_key, (mn, mx, avg, cnt) in stats.items():
                print(
                    f"Spacing {ch_name(ch_key)}: count={int(cnt)} min={mn:.6f}s max={mx:.6f}s avg={avg:.6f}s",
                    file=sys.stderr,
                )
    except Exception as e:
        print(f"Failed to write output: {e}", file=sys.stderr)
        sys.exit(1)

    if a.keep_bad and bad:
        bad_path = a.outfile + ".bad"
        try:
            with open(bad_path, "wb") as fb:
                fb.write(bad)
            print(
                f"Wrote {len(bad)} bytes of rejected frames to {bad_path}",
                file=sys.stderr,
            )
        except Exception as e:
            print(f"Warning: could not write .bad file: {e}", file=sys.stderr)

    print(
        f"Decoded frames_ok={frames_ok} crc_fail={crc_fail} bytes_scanned={scanned} channels_seen={len(per_ch)}",
        file=sys.stderr,
    )


if __name__ == "__main__":
    main()
